UPDATE cases
SET title = (
      SELECT scopes.scope || CASE CAST(substr(cases.case_id,-4) AS INTEGER) % 3 WHEN 1 THEN 'installation work hours translatedtranslated' WHEN 2 THEN 'restore original conditiontranslatedtranslated' ELSE 'translatedtranslatedauthorizationtranslatedtranslated' END
      FROM scopes WHERE scopes.n=CAST((CAST(substr(cases.case_id,-4) AS INTEGER)+2)/3 AS INTEGER)
    ),
    parties = 'translatedtranslatedizedtranslatedtranslatedandtranslatedtranslatedtranslated',
    summary = (
      SELECT 'translatedtranslatedfilesizedbusinesscase：translatedtranslated' || scopes.scope || CASE CAST(substr(cases.case_id,-4) AS INTEGER) % 3 WHEN 1 THEN 'ofinstallation work hours responsibilitytranslatedtranslated' WHEN 2 THEN 'ofmove-outrestorationcoststranslatedtranslated' ELSE 'oftranslatedtranslatedauthorizationboundary' END || '；must notalternativetranslatedtranslatedtranslatedtranslatedtranslatedtranslatedtranslatedcontracttranslatedsee。'
      FROM scopes WHERE scopes.n=CAST((CAST(substr(cases.case_id,-4) AS INTEGER)+2)/3 AS INTEGER)
    ),
    facts = (
      SELECT 'translatedtranslatedtranslatedtranslatedtranslatedcompleteas' || scopes.scope || '；currentrecordtranslatedtranslated' || scopes.constraint_fact || CASE CAST(substr(cases.case_id,-4) AS INTEGER) % 3 WHEN 1 THEN '，translatedtranslatedtranslatedtranslatedtranslatedtranslatedtranslatedtranslatedroomtranslatedtranslatedandneighbornotification。' WHEN 2 THEN '，translatedtranslatedtranslatedtranslatedtranslatedtranslatedtranslatedremovaltranslatedtranslatedandreasonablefixtranslatedrange。' ELSE '，translatedtranslatedtranslatedtranslatedtranslatedtranslatedtranslatedfixedtranslatedtranslatedwhethertranslatedtranslatedtranslatedtranslatedsametranslated。' END
      FROM scopes WHERE scopes.n=CAST((CAST(substr(cases.case_id,-4) AS INTEGER)+2)/3 AS INTEGER)
    ),
    reasoning = (
      SELECT 'materialstranslatedtranslatedthantranslated' || CASE CAST(substr(cases.case_id,-4) AS INTEGER) % 3 WHEN 1 THEN 'property managementallowed hours andneighbornotification' WHEN 2 THEN 'translatedtranslatedtranslatedaccording totranslatedandmove-outtranslatedtranslated' ELSE 'leasetranslatedtranslatedandtranslatedtranslatedtranslatedtranslatedreply' END || '，translatedverify' || scopes.scope || 'of can translatedtranslatedtranslatedtranslated“' || scopes.constraint_fact || '”translatedtranslatedevidence。'
      FROM scopes WHERE scopes.n=CAST((CAST(substr(cases.case_id,-4) AS INTEGER)+2)/3 AS INTEGER)
    ),
    holding = (
      SELECT CASE CAST(substr(cases.case_id,-4) AS INTEGER) % 3
        WHEN 1 THEN 'installation work hours evidencecompleteoftranslatedtranslatedtranslatedtranslatedtranslatedtranslatedresponsibility；more thantranslatedtranslatedtranslatedpartialonetranslatedlocationstranslated。'
        WHEN 2 THEN 'restorationcostsaccording tooriginaltranslatedaccording totranslated、translatedtranslatedtranslatedtranslatedandreasonablefixtranslatedrangetranslatedtranslated。'
        ELSE 'more thantranslatedtranslatedtranslatedauthorizationoffixedtranslatedtranslated not translated is translatedtranslatedtranslatedtranslated，musttranslatedtranslatedconfirm。'
      END || ' translatedtranslatedobjects is ' || scopes.scope || '。'
      FROM scopes WHERE scopes.n=CAST((CAST(substr(cases.case_id,-4) AS INTEGER)+2)/3 AS INTEGER)
    ),
    ruling = CASE CAST(substr(case_id,-4) AS INTEGER) % 3 WHEN 1 THEN ' hours responsibilitypartially supported' WHEN 2 THEN 'reasonablerestorationcostspartially supported' ELSE 'translatedtranslatedauthorizationpartial not translatedsupport' END,
    outcome = CASE CAST(substr(case_id,-4) AS INTEGER) % 3 WHEN 1 THEN 'partially supported' WHEN 2 THEN 'support' ELSE 'translatedtranslated' END,
    keywords = (
      SELECT 'translatedtranslatedfilesizedcase rentalspace ' || scopes.scope || ' noise reversible translatedtranslatedauthorization ' || CASE CAST(substr(cases.case_id,-4) AS INTEGER) % 3 WHEN 1 THEN 'installation work hours andneighbornotification' WHEN 2 THEN 'move-outfixtranslatedandcostsrange' ELSE 'fixedtranslatedtranslatedandauthorizationboundary' END
      FROM scopes WHERE scopes.n=CAST((CAST(substr(cases.case_id,-4) AS INTEGER)+2)/3 AS INTEGER)
    )
WHERE case_id GLOB 'case_[0-9][0-9][0-9][0-9]';
